// TH16 v1.00a st03 MainSub01 (st03.ecl.txt:1154-1210)
// Shell: 120-frame opening buffer, then source t=0 (two GirlD01) through
// MainSub01b's four GirlA02 groups and the tail of the last ring.
const TIME_LIMIT: int = 974;
const OPENING_BUFFER: int = 120;

const RING_BALL_COLOR: int = 1;   // etSprite(0,18,1)  -> TH16_BIG_BALL
const RICE_COLOR: int = 4;        // SHOOT_DATA a=8,b=4 -> TH16_RICE

// ---- GirlA02 -----------------------------------------------------------------
// GirlA02F (st03.ecl.txt:421-439): body boxes, aim at (0,448), then re-aim at the
// player at script t=120 and t=240.  `moveVelTime(...,mode 1)` = EASE_QUAD_IN.
// GirlA02() never calls GirlA02_at in st03 (that sub has no caller), so this
// enemy only moves and collides.
async sub girl_a02() {
    set_invuln(65535);
    set_hurtbox(12fx);            // setHurtbox(24,24): first value * 0.5
    set_hitbox(8fx);              // setHitbox(16,16): first value * 0.5
    var aim: angle = atan2(448fx - $self_y, 0fx - $self_x);  // getAngle(%F2, FINAL, 0,448)
    move_vel(0, 90deg, 1fx, EASE_LINEAR);                    // moveVel(pi/2, 1.0)
    move_vel(60, aim, 1.3fx, EASE_LINEAR);                   // moveVelTime(60,0,%F2,1.3)
    wait(120);                                               // +120
    move_vel(60, aim_player(), 1.3fx, EASE_LINEAR);          // %ANGLE_PLAYER read at t=120
    wait(120);                                               // +120 : t=240
    move_vel(60, aim_player(), 1.3fx, EASE_LINEAR);          // %ANGLE_PLAYER read at t=240
    loop { wait(1000); }                                     // GirlA02F_292 wait(1000) loop
}

// MainSub01b (st03.ecl.txt:1163-1210): four groups of five mirrored pairs.
// %A runs -16,-56,-96,-136,-176 at y=-64; item 1/2 is a drop and omitted.
sub main_sub01b() {
    var a: fx = -16fx;
    for round in 0..4 {
        a = -16fx;
        for i in 0..5 {
            _ = spawn_enemy(a, -64fx, 130, 0, 1000, 0, girl_a02);
            _ = spawn_enemy(-a, -64fx, 130, 0, 1000, 0, girl_a02);
            a = a - 40fx;
            wait(10);
        }
        if round == 0 { wait(80); }
        if round == 1 { wait(70); }
        if round == 2 { wait(50); }
    }
}

// ---- GirlD01 -----------------------------------------------------------------
// Bullet EX chain of the big ball (st03.ecl.txt:838-854):
//   idx1 WAIT20, idx2 WAIT8, idx3 SHOOT(1x1, angle kept, speed 0), idx5 GOTO idx2
//   with b = 6/6/8/11 jumps.  A bullet task first runs one frame after spawn, so
//   wait(27) puts the first child at source +28 and later ones every 8 frames.
// Children copy EX from idx10: ANIM (omitted), WAIT100, ANGLE_ACCEL(120, r, s=0).
async sub big_ball_child_shots() {
    var shots: int = 7;           // b=6 -> first shot + 6 jumps
    var accel: fx = 0.01fx;       // ANGLE_ACCEL r = 0.01
    if global(GVAR_RANK) >= RANK_HARD { shots = 9; accel = 0.03fx; }   // b=8
    if global(GVAR_RANK) == RANK_LUNATIC { shots = 12; }              // b=11
    wait(27);
    for i in 0..shots {
        _ = fire(TH16_RICE, RICE_COLOR, $self_x, $self_y, 0fx, $self_angle,
                 RICE_ACCEL(accel), none);
        wait(8);
    }
}

xformdef RICE_ACCEL(accel: fx) {
    @100 add_speed(0fx);          // EX idx11 WAIT 100 (idx10 ANIM omitted)
    @120 set_accel(accel);        // EX idx12 ANGLE_ACCEL: 120 steps, s=0
    set_accel(0fx);
}

// GirlD01_at (st03.ecl.txt:819-882): wait 60, then five rings of
// etCount = 10/10/10/16 around, speed 2.3, type 18 color 1.
async sub girl_d01_at() {
    wait(60);
    var n: int = 10;
    var gap: int = 125;
    if global(GVAR_RANK) >= RANK_HARD { gap = 60; }
    if global(GVAR_RANK) == RANK_LUNATIC { n = 16; }
    sh_reset(0);
    sh_sprite(0, TH16_BIG_BALL, RING_BALL_COLOR);
    sh_aim(0, 0);
    sh_ring(0, 1);                // etAim(0,3): fixed-direction full ring
    sh_count(0, n, 1);
    sh_angle(0, 0deg, 273bam);    // etAngle(0,0,0.02617994): 1.5deg layer step, M=1
    sh_speed(0, 2.3fx, 0fx);
    sh_task(0, big_ball_child_shots);
    for i in 0..5 {               // $A = 5 emissions
        sh_fire(0);
        wait(gap);
    }
}

// GirlD01 (st03.ecl.txt:793-817).  The +128 body is enmCreateM (mirror set), so
// its movement angles are reflected about the vertical axis; firing angles are
// not mirrored.  moveVelTime/moveSpeedTime mode 1 = EASE_QUAD_IN.
async sub girl_d01(mirror: int) {
    set_invuln(65535);
    set_hurtbox(16fx);            // setHurtbox(32,32)
    set_hitbox(12fx);             // setHitbox(24,24)
    move_vel(0, 90deg, 2.5fx, EASE_LINEAR);        // moveVel(pi/2, 2.5)
    move_vel(70, 90deg, 0fx, EASE_QUAD_IN);        // moveVelTime(70,1,pi/2,0.0)
    spawn girl_d01_at();                           // @GirlD01_at() async
    wait(80);
    move_speed(120, 0.2fx, EASE_QUAD_IN);          // moveSpeedTime(120,1,0.2)
    wait(120);
    var a: angle = 2048bam;      // 0.19634955 rad = 11.25deg
    if mirror != 0 { a = 30720bam; }               // mirrored: pi - 0.19634955
    move_vel(70, a, 0.8fx, EASE_QUAD_IN);          // moveVelTime(70,1,0.19634955,0.8)
    loop { wait(1000); }                           // GirlD01_460/480 loop
}

// ---- Wave entry --------------------------------------------------------------
// MainSub01 (st03.ecl.txt:1154-1161): two GirlD01 at (+-128,-24), wait 120,
// then MainSub01b async.  The synchronous call keeps the same timeline.
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(128fx, -24fx, 2000, 0, 1000, 0, girl_d01(1));   // enmCreateM
    _ = spawn_enemy(-128fx, -24fx, 2000, 0, 1000, 0, girl_d01(0));  // enmCreate
    wait(120);
    main_sub01b();
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

